claims.quote:
empty: {
    text: 'There are no notifications yet.',
    startButton: 'Start a new notification'
  }

{% if isEmpty %}
    <p class="govuk-body" data-testid="dashboard-empty">{{ copy.empty.text }}</p>
    {{ govukButton({
      text: copy.empty.startButton,
      href: startNewNotificationHref
    }) }}

const headers = () => ({
  'Content-Type': 'application/json',
  [tracingHeader]: getTraceId() ?? ''
})

recoverableError: {
    title: 'There is a problem',
    body: 'Sorry, there is a problem with the service. Try again in a few minutes.'
  },

phaseBanner: {
      tag: 'Alpha',
      bodyPrefix: 'This is a new service. Help us improve it and',
      feedbackLinkText: 'give your feedback by email'
    },

footer: {
      privacy: 'Privacy',
      cookies: 'Cookies',
      accessibility: 'Accessibility statement'
    }

{% if journeyStrip %}
        <div class="app-journey-strip govuk-!-margin-bottom-4">
          {{ govukTag({ text: journeyStrip.status.text, classes: journeyStrip.status.classes }) }}

errorSummary: {
    title: 'There is a problem'
  },

const countryCode =
      request.query.countryCode?.trim() ||
      resolveCountryCodeFromSearchTerm(q, countries)

name: {
      required: 'Enter a name',
      maxLength: (max) => `Name must be ${max} characters or fewer`
    },

if (errors) {
      return buildView(h, {
        formValues,
        countryItems: countryItemsOf(countries),
        errors,
        handshake
      }).code(HTTP_STATUS_BAD_REQUEST)

const addressesUrl = (orgId, addressId) => {
  if (!orgId) {
    throw new Error(
      'Cannot reach the address book without an organisation: the signed-in session carries none'
    )
  }

if (!journeyType || !notificationId || !fulfilmentId || !handshakeToken) {
    throw Boom.badRequest('Incomplete journey handshake')
  }
